.text
    
    # #a0, manda posicion actual de la pantalla
funcion_menu:
    
    addi $sp, $sp, -8
    sw $ra, ($sp)
    sw $s0, 4($sp)
    
    move $s0, $a0
   

    loop_correccion_boton:
    jal Polling
    move $t0, $v0
    beq $t0, 'u', operacion_menu
    beq $t0, 'j', operacion_menu
    beq $t0, $zero, operacion_menu # aca tendria que entrar al boton en el que esta, o sea llamar a la funcion
    j loop_correccion_boton

    operacion_menu:    
    move $a0, $t0
    move $a1, $s0
    jal accionar_menu

    lw $s0, 4($sp)
    lw $ra, ($sp)
    addi $sp, $sp, 8    
    
jr $ra



    # $a0 -> valor de izquierda derecha o aceptar
    # $a1 -> posicion en la pantalla en la cual me encuentro
accionar_menu:
    
    addi $sp, $sp, -8
    sw $ra, ($sp)
    sw $s0, 4($sp)
    
    move $t0, $a0
    move $s0, $a1
    beq $t0, 'u', muevo_izquierda
    beq $t0, 'j', muevo_derecha
    beq $t0, $zero, fin_accionar_menu

    muevo_izquierda:
    beqz $s0, imprimo_pantalla
    addi $s0, $s0, -1
    j imprimo_pantalla

    muevo_derecha:
    beq $s0, 5, imprimo_pantalla
    addi $s0, $s0, 1   
    j imprimo_pantalla    

    imprimo_pantalla:   
    beq $s0, 0, Piano
    beq $s0, 1, Grabar_melodia
    beq $s0, 2, Reproducir_flash
    beq $s0, 3, Reproducir_melodia1
    beq $s0, 4, Reproducir_melodia2
    beq $s0, 5, Reproducir_melodia3


    Piano:
    la $a1, img_menu_piano
    j fin_impresion_menu

    Grabar_melodia:
    la $a1, img_menu_grabar
    j fin_impresion_menu

    Reproducir_flash:
    la $a1, img_menu_flash
    j fin_impresion_menu

    Reproducir_melodia1:
    la $a1, img_menu_melodia1
    j fin_impresion_menu

    Reproducir_melodia2:
    la $a1, img_menu_melodia2
    j fin_impresion_menu

    Reproducir_melodia3:
    la $a1, img_menu_melodia3
    j fin_impresion_menu


    fin_impresion_menu:
    move $a0, $a1
    jal imprimir_bitmap

    fin_accionar_menu:
    # devuelvo el valor en donde estoy parado del menu
    move $v0, $s0
    move $v1, $t0
    
    lw $s0, 4($sp)
    lw $ra, ($sp)
    addi $sp, $sp, 8
    
jr $ra
    
    

funcion_piano: # void funcion_piano()
    
    
	addi $sp, $sp, -8
	sw $ra, ($sp)
	sw $s0, 4($sp)
	
	loop_piano:
	la $a0, img_piano_base
	jal imprimir_bitmap
	
	# Hago polling y recibo la nota que estoy tocando
	jal Polling
	
	move $t0, $v0
	beq $t0, 1, loop_piano
	beqz $t0, fin_piano
	
	move $a0, $v0
	jal asignar_nota

	move $a0, $v0 # Address imagen nota 
	move $s0, $v1 # PR nota

	jal imprimir_bitmap

	move $a0, $s0 
	jal Suena_Buzzer 
	
	j loop_piano
	
	
	fin_piano:
	lw $ra, ($sp)
	lw $s0, 4($sp)
	addi $sp, $sp, 8
	
jr $ra
    
    
    
     
funcion_grabacion: # void funcion_grabacion()
    
    
	addi $sp, $sp, -12   
	sw $ra, 0($sp)
	sw $s0, 4($sp)
	sw $s1, 8($sp)

	la $a0, img_piano_base
	jal imprimir_bitmap
	
	jal Clear_Flash
	jal Borrar_Row    

	li $t0, 1
	sw $t0, Flag_Guardar # Levanto Flag para guardar en la flash la row construida

	loop_Reproducir_Y_Guardar:
	
	la $a0, img_piano_base
	jal imprimir_bitmap
    
	jal Polling
	beq $v0, 0, Volver_Menu

	move $s1, $v0   # Arreglar para nuevas funciones
	
	move $a0, $s1
	jal asignar_nota

	move $a0, $v0 # Address imagen nota 
	move $s0, $v1 # PR nota

	jal imprimir_bitmap

	move $a0, $s0 
	jal Suena_Buzzer 

	move $a0, $s1

	jal AlmacenarNotaRow

	j loop_Reproducir_Y_Guardar

	Volver_Menu:
	
	
	lw $ra, 0($sp)
	lw $s0, 4($sp)
	lw $s1, 8($sp)
	addi $sp, $sp, 12

jr $ra
    
funcion_melodia: # void funcion_melodia( $a0, direccion inicial array melodia)
    
	    addi $sp, $sp, -12
	    sw $ra, ($sp)
	    sw $s0, 4($sp)
	    sw $s1, 8($sp)
	    
	    move $s1, $a0
	    loop_Recorrer_Melodia:
	    
	    lb $t1, ($s1)
	    beq $t1, $zero, Fin_Recorrer_Melodia
	    
	    move $a0, $t1
	    jal asignar_nota

	    move $a0, $v0 # Address imagen nota 
	    move $s0, $v1 # PR nota

	    jal imprimir_bitmap

	    move $a0, $s0 
	    jal Suena_Buzzer 
	    
	    
	    addiu $s1, $s1, 1
	    j loop_Recorrer_Melodia
	    
	    Fin_Recorrer_Melodia:
    
	    lw $ra, 0($sp)
	    lw $s0, 4($sp)
	    lw $s1, 8($sp)
	    addi $sp, $sp, 12
	    
    jr $ra
    
    